import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 58 A spot of bother","description":"学习 but for 与 without 的隐含条件，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 58 A spot of bother","description":"学习 but for 与 without 的隐含条件，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 but for 与 without 的隐含条件，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 57 Back in the old country","link":"/life/english/new-concept/book-3/unit-03/lesson-057"},"next":{"text":"第三册：培养技能 · Lesson 59 Collecting","link":"/life/english/new-concept/book-3/unit-03/lesson-059"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 57 Back in the old country","link":"/life/english/new-concept/book-3/unit-03/lesson-057"},"next":{"text":"第三册：培养技能 · Lesson 59 Collecting","link":"/life/english/new-concept/book-3/unit-03/lesson-059"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-058.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-058.md"}'),i={name:"life/english/new-concept/book-3/unit-03/lesson-058.md"};function r(l,e,s,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-58-a-spot-of-bother" tabindex="-1">第三册：培养技能 · Lesson 58 A spot of bother <a class="header-anchor" href="#第三册-培养技能-·-lesson-58-a-spot-of-bother" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 58 A spot of bother&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从小误会逐渐扩大的生活事件练习表达“要不是某条件，结果会怎样”。叙述要分清麻烦本身、误解来源和解决线索。学习 but for 与 without 的反事实用法，将冗长条件压缩为名词短语，但保持主句的时间层次和否定范围准确。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>misunderstanding</td><td>/ˌmɪsʌndəˈstændɪŋ/</td><td>n.</td><td>误解</td><td>clear up a misunderstanding</td></tr><tr><td>receipt</td><td>/rɪˈsiːt/</td><td>n.</td><td>收据</td><td>show a receipt</td></tr><tr><td>awkward</td><td>/ˈɔːkwəd/</td><td>adj.</td><td>尴尬的</td><td>an awkward situation</td></tr><tr><td>resolve</td><td>/rɪˈzɒlv/</td><td>v.</td><td>解决</td><td>resolve a dispute</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>clear up — 澄清或解决误会</li><li>but for — 要不是某因素，用于隐含条件</li></ul><h2 id="语法讲解-but-for-与-without-的隐含条件" tabindex="-1">语法讲解：but for 与 without 的隐含条件 <a class="header-anchor" href="#语法讲解-but-for-与-without-的隐含条件" aria-label="Permalink to &quot;语法讲解：but for 与 without 的隐含条件&quot;">​</a></h2><p>but for 加名词短语可表示“要不是”，在反事实语境中相当于 if it were not for 或 if it had not been for。主句若描述现在或一般结果，用 would do；若描述过去不同结果，用 would have done。without 也可承担类似条件意义，但它还可以只是普通“没有”的伴随说明，因此需结合主句判断。but for 中的 but 不是连接两个分句的转折连词，后面通常不直接接完整句。压缩条件时应保留关键名词，避免指代不明。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>But for the dated receipt, we would have been unable to explain the mix-up.</p></blockquote><p>要不是那张有日期的收据，我们就无法解释这次混淆了。</p><p>but for 引出过去反事实条件，would have been unable 描述过去本可能出现的结果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>But for she helped us 结构不成立，应写 But for her help，或 If she had not helped us。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 But for the tracking message 后稍停，在 would have continued 上保留 have，避免过去反事实被听成现在条件。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The clerk thought I had collected the parcel already. But for the tracking message, the mistake would have continued. We checked the reference number and found a second customer with the same surname.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句小误会的处理过程，包含一项决定性线索。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>误解、关键证据和具体核查组成因果链，未仅靠人物情绪推动结局。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句收据实际存在吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 存在。</p><p><strong>解析：</strong> 反事实“要不是收据”暗示实际有该证据帮助。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改写 But for your help（过去语境）。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> If you had not helped us</p><p><strong>解析：</strong> 用过去完成时展开隐含条件。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：Without the map, we would have ___ lost.（been/be）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 完成结构要求 be 的过去分词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：but for 与 without 的隐含条件。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-057">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-059">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",r]]);export{p as __pageData,b as default};
